WHERE p.deleted = 0

  AND (p.purchase_no LIKE CONCAT('%', #{keyword}, '%')
    OR p.platform_order_no LIKE CONCAT('%', #{keyword}, '%')
    OR p.seller_account LIKE CONCAT('%', #{keyword}, '%')
    OR bp.product_name LIKE CONCAT('%', #{keyword}, '%'))


  AND p.purchase_status = #{purchaseStatus}


  AND p.purchase_date >= #{startDate}


  AND p.purchase_date <= #{endDate}


  AND EXISTS (
    SELECT 1
    FROM biz_purchase_item pi_filter
    WHERE pi_filter.purchase_id = p.id
      AND pi_filter.deleted = 0
      AND pi_filter.product_id IN

        #{productId}

  )
